namespace Bsft.Messaging.EFCore.Tests.Support;

/// <summary>Cuts one table's CREATE TABLE statement out of an EF Core create script.</summary>
internal static class CreateScript
{
    /// <summary>
    /// Extracts a single table's CREATE TABLE statement from a complete create script.
    /// </summary>
    /// <param name="script">The full create script generated by EF Core.</param>
    /// <param name="table">The table name to extract.</param>
    /// <returns>The CREATE TABLE statement for that table.</returns>
    /// <exception cref="InvalidOperationException">Thrown when the table is not found in the script.</exception>
    public static string Table(string script, string table)
    {
        var start = script.IndexOf($"CREATE TABLE \"{table}\" (", StringComparison.Ordinal);
        if (start < 0)
            throw new InvalidOperationException($"The create script has no table {table}.");
        var end = script.IndexOf(");", start, StringComparison.Ordinal);
        return script[start..(end + 2)];
    }
}
